using System.Security.Claims;using HealthTracker.Api.Contracts;using HealthTracker.Api.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;namespace HealthTracker.Api.Controllers;[ApiController][Route("api/auth")]public class AuthController(IAuthService a):ControllerBase{[HttpPost("register")]public async Task<ActionResult<AuthResponse>> Register(RegisterRequest r){try{return Ok(await a.Register(r));}catch(InvalidOperationException e){return Conflict(new{message=e.Message});}}[HttpPost("login")]public async Task<ActionResult<AuthResponse>> Login(LoginRequest r){try{return Ok(await a.Login(r));}catch(UnauthorizedAccessException e){return Unauthorized(new{message=e.Message});}}[Authorize][HttpGet("me")]public ActionResult<UserResponse> Me(){var userId=Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);var email=User.FindFirstValue(ClaimTypes.Email)!;var displayName=User.Identity?.Name??"";var user=new HealthTracker.Api.Contracts.UserResponse(userId,email,displayName);return Ok(user);}}